  "glossary": [
    {
      "en": "Agent",
      "es": "Agente",
      "definition": "A system that selects actions from observations or internal state.",
      "unit": 1
    },
    {
      "en": "Actuator",
      "es": "Actuador",
      "definition": "A mechanism through which an agent changes its environment.",
      "unit": 1
    },
    {
      "en": "Percept",
      "es": "Percepción",
      "definition": "An observation available to the agent at a particular time.",
      "unit": 1
    },
    {
      "en": "Rationality",
      "es": "Racionalidad",
      "definition": "Choosing actions that maximise expected performance given available information.",
      "unit": 1
    },
    {
      "en": "PEAS",
      "es": "Rendimiento, entorno, actuadores y sensores",
      "definition": "A framework for specifying an agent task.",
      "unit": 1
    },
    {
      "en": "Partial observability",
      "es": "Observabilidad parcial",
      "definition": "The observation does not reveal all decision-relevant state.",
      "unit": 1
    },
    {
      "en": "State space",
      "es": "Espacio de estados",
      "definition": "The states and transitions admitted by a problem model.",
      "unit": 2
    },
    {
      "en": "Frontier",
      "es": "Frontera",
      "definition": "Discovered search nodes waiting to be expanded.",
      "unit": 2
    },
    {
      "en": "Path cost",
      "es": "Coste del camino",
      "definition": "The sum of action costs along a path.",
      "unit": 2
    },
    {
      "en": "Completeness",
      "es": "Completitud",
      "definition": "A guarantee of finding a solution when one exists under stated assumptions.",
      "unit": 2
    },
    {
      "en": "Optimality",
      "es": "Optimalidad",
      "definition": "A guarantee of returning a solution with minimum cost under stated assumptions.",
      "unit": 2
    },
    {
      "en": "Cutoff",
      "es": "Interrupción por límite",
      "definition": "A search stopped by a resource limit; not proof of unsolvability.",
      "unit": 2
    },
    {
      "en": "Heuristic",
      "es": "Heurística",
      "definition": "An estimate used to guide a search decision.",
      "unit": 3
    },
    {
      "en": "Admissibility",
      "es": "Admisibilidad",
      "definition": "A heuristic never overestimates the optimal remaining cost.",
      "unit": 3
    },
    {
      "en": "Consistency",
      "es": "Consistencia",
      "definition": "For every edge, h(n) is at most its cost plus h(n′).",
      "unit": 3
    },
    {
      "en": "Reopening",
      "es": "Reapertura",
      "definition": "Expanding a state again after discovering a better path to it.",
      "unit": 3
    },
    {
      "en": "Dominance",
      "es": "Dominancia",
      "definition": "One admissible heuristic is at least as large as another at every state.",
      "unit": 3
    },
    {
      "en": "Tie-breaking",
      "es": "Desempate",
      "definition": "A specified rule for choosing among equal-priority candidates.",
      "unit": 3
    },
    {
      "en": "Domain",
      "es": "Dominio",
      "definition": "The current candidate values for a CSP variable.",
      "unit": 4
    },
    {
      "en": "Constraint",
      "es": "Restricción",
      "definition": "A condition that valid assignments must satisfy.",
      "unit": 4
    },
    {
      "en": "Arc consistency",
      "es": "Consistencia de arco",
      "definition": "Every remaining value has support in the neighbouring variable on that arc.",
      "unit": 4
    },
    {
      "en": "Forward checking",
      "es": "Comprobación hacia delante",
      "definition": "Removing incompatible values from unassigned neighbours after an assignment.",
      "unit": 4
    },
    {
      "en": "MRV",
      "es": "Mínimos valores restantes",
      "definition": "Choose an unassigned variable with the smallest current domain.",
      "unit": 4
    },
    {
      "en": "Global constraint",
      "es": "Restricción global",
      "definition": "A constraint involving a collection of variables, such as AllDifferent.",
      "unit": 4
    },
    {
      "en": "Minimax",
      "es": "Minimax",
      "definition": "Choose against an optimal opponent in a zero-sum decision model.",
      "unit": 5
    },
    {
      "en": "Alpha–beta pruning",
      "es": "Poda alfa–beta",
      "definition": "Skip branches that cannot change the minimax root decision.",
      "unit": 5
    },
    {
      "en": "Evaluation function",
      "es": "Función de evaluación",
      "definition": "An estimate of position quality at a search cutoff.",
      "unit": 5
    },
    {
      "en": "Expectimax",
      "es": "Expectimax",
      "definition": "Back up expected utility at chance nodes and choices at decision nodes.",
      "unit": 5
    },
    {
      "en": "Utility",
      "es": "Utilidad",
      "definition": "The numerical preference measure used by the decision model.",
      "unit": 5
    },
    {
      "en": "Move ordering",
      "es": "Ordenación de movimientos",
      "definition": "The order in which successor actions are considered.",
      "unit": 5
    },
    {
      "en": "MDP",
      "es": "Proceso de decisión de Markov",
      "definition": "A model of states, actions, transitions, rewards and an objective.",
      "unit": 6
    },
    {
      "en": "Return",
      "es": "Retorno",
      "definition": "The accumulated, possibly discounted, future reward.",
      "unit": 6
    },
    {
      "en": "Discount factor",
      "es": "Factor de descuento",
      "definition": "The weight gamma applied per future time step.",
      "unit": 6
    },
    {
      "en": "Bellman backup",
      "es": "Actualización de Bellman",
      "definition": "A value update using immediate reward and successor values.",
      "unit": 6
    },
    {
      "en": "Temporal difference",
      "es": "Diferencia temporal",
      "definition": "Learning from a sampled reward and a bootstrapped value estimate.",
      "unit": 6
    },
    {
      "en": "Q-learning",
      "es": "Q-learning",
      "definition": "An off-policy update that uses the largest next-action value.",
      "unit": 6
    },
    {
      "en": "SARSA",
      "es": "SARSA",
      "definition": "An on-policy update using the next action actually selected.",
      "unit": 6
    },
    {
      "en": "Exploration",
      "es": "Exploración",
      "definition": "Taking actions to obtain information rather than only exploiting current estimates.",
      "unit": 6
    },
    {
      "en": "Termination",
      "es": "Terminación",
      "definition": "The task reaches a genuine terminal state.",
      "unit": 6
    },
    {
      "en": "Truncation",
      "es": "Truncamiento",
      "definition": "An external limit stops interaction without necessarily terminating the underlying task.",
      "unit": 6
    }
  ],
